/* Generated by standOfflinePlugin at build time. Scope is /stand/ only. */
const CONFIG = __STAND_OFFLINE_CONFIG__;
const PREFIX = 'luca-stand-';
const CACHE = PREFIX + CONFIG.version;
const SHELL = new Set(CONFIG.shell);
const VIDEOS = new Set(CONFIG.videos);
let disabled = false;

function valid(response, pathname) {
  if (response.status !== 200) return false;
  const type = response.headers.get('content-type') || '';
  if (pathname === '/stand/') return type.includes('text/html');
  if (/\.js$/.test(pathname)) return /javascript/.test(type);
  if (/\.css$/.test(pathname)) return type.includes('text/css');
  if (VIDEOS.has(pathname)) return type.includes('video/');
  return type.startsWith('image/');
}

async function disable() {
  disabled = true;
  await self.registration.unregister();
  await Promise.all((await caches.keys()).filter((key) => key.startsWith(PREFIX)).map((key) => caches.delete(key)));
}

async function removed() {
  try {
    const response = await fetch('/stand/sw.js', { cache: 'no-store', signal: AbortSignal.timeout(4000) });
    if (response.status === 404 || response.headers.get('content-type')?.includes('text/html')) {
      await disable();
      return true;
    }
  } catch { /* Offline is not an instruction to uninstall. */ }
  return false;
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // A complete shell is required. Videos are optional if storage is full.
    for (const pathname of CONFIG.shell) {
      const response = await fetch(pathname, { cache: 'reload', credentials: 'omit' });
      if (!valid(response, pathname)) throw new Error('Invalid offline shell: ' + pathname);
      await cache.put(pathname, response);
    }
    for (const pathname of CONFIG.videos) {
      try {
        const response = await fetch(pathname, { cache: 'reload', credentials: 'omit' });
        if (valid(response, pathname)) await cache.put(pathname, response);
      } catch { /* The online stand remains usable if video caching fails. */ }
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    await Promise.all((await caches.keys()).filter((key) => key.startsWith(PREFIX) && key !== CACHE).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

async function videoResponse(request, cached) {
  const range = request.headers.get('range');
  if (!range) return cached;
  const bytes = await cached.arrayBuffer();
  const match = /^bytes=(\d*)-(\d*)$/.exec(range);
  const start = match?.[1] ? Number(match[1]) : match?.[2] ? Math.max(0, bytes.byteLength - Number(match[2])) : NaN;
  const end = match?.[1] && match[2] ? Math.min(Number(match[2]), bytes.byteLength - 1) : bytes.byteLength - 1;
  if (!Number.isSafeInteger(start) || start < 0 || start > end || start >= bytes.byteLength) {
    return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${bytes.byteLength}` } });
  }
  const headers = new Headers(cached.headers);
  headers.set('Content-Range', `bytes ${start}-${end}/${bytes.byteLength}`);
  headers.set('Content-Length', String(end - start + 1));
  headers.set('Accept-Ranges', 'bytes');
  return new Response(bytes.slice(start, end + 1), { status: 206, headers });
}

async function serve(request, pathname) {
  const navigation = request.mode === 'navigate';
  if (navigation && await removed()) return fetch(request);
  if (disabled) return fetch(request);
  const key = navigation ? '/stand/' : pathname;
  if (VIDEOS.has(key)) {
    const cached = await caches.match(key, { cacheName: CACHE });
    return cached ? videoResponse(request, cached) : fetch(request);
  }
  try {
    const response = await fetch(request, { signal: AbortSignal.timeout(4000) });
    if (!valid(response, key)) throw new Error('Invalid shell response');
    return response;
  } catch (error) {
    const cached = await caches.match(key, { cacheName: CACHE });
    if (cached) return cached;
    throw error;
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (disabled) return;
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;
  // Explicit allowlist: no API, WS, other app page, auth payload or arbitrary asset.
  const navigation = request.mode === 'navigate' && /^\/stand\/?$/.test(url.pathname);
  if (!navigation && !SHELL.has(url.pathname) && !VIDEOS.has(url.pathname)) return;
  event.respondWith(serve(request, url.pathname));
});
